package main

import (
	"encoding/json"
	"log"
	"net/http"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

type TenantConfig struct {
	Properties map[string]interface{}
	mu         sync.RWMutex
}

type Server struct {
	tenants  map[string]*TenantConfig
	defaults *TenantConfig
	mu       sync.RWMutex
	upgrader websocket.Upgrader
}

// allowedOrigins is the set of origins permitted to open WebSocket connections.
var allowedOrigins = map[string]bool{
	"https://app.example.com": true,
}

func checkOrigin(r *http.Request) bool {
	origin := r.Header.Get("Origin")
	if origin == "" {
		// Reject requests with no Origin header to avoid cross-site hijacking.
		return false
	}
	return allowedOrigins[origin]
}

func NewServer() *Server {
	defaults := &TenantConfig{
		Properties: map[string]interface{}{
			"maxConnections": 100,
			"rateLimit":      1000,
			"features": map[string]interface{}{
				"chat":    true,
				"upload":  false,
				"admin":   false,
			},
		},
	}
	return &Server{
		tenants:  make(map[string]*TenantConfig),
		defaults: defaults,
		upgrader: websocket.Upgrader{CheckOrigin: checkOrigin},
	}
}

func (s *Server) getTenantConfig(tenantID string) *TenantConfig {
	s.mu.RLock()
	tc, exists := s.tenants[tenantID]
	s.mu.RUnlock()
	if exists {
		return tc
	}
	// Initialize new tenant from defaults
	s.mu.Lock()
	defer s.mu.Unlock()
	// Double-check after acquiring write lock
	if tc, exists = s.tenants[tenantID]; exists {
		return tc
	}
	newTC := &TenantConfig{
		Properties: s.cloneProperties(s.defaults.Properties),
	}
	s.tenants[tenantID] = newTC
	return newTC
}

func (s *Server) cloneProperties(src map[string]interface{}) map[string]interface{} {
	result := make(map[string]interface{})
	for k, v := range src {
		switch val := v.(type) {
		case map[string]interface{}:
			// Deep copy for nested maps - ensures tenant isolation
			result[k] = s.cloneProperties(val)
		default:
			result[k] = v
		}
	}
	return result
}

func (s *Server) applyUpdate(config *TenantConfig, path string, value interface{}) {
	config.mu.Lock()
	defer config.mu.Unlock()

	parts := strings.Split(path, ".")
	if len(parts) == 0 {
		return
	}

	current := config.Properties
	for i := 0; i < len(parts)-1; i++ {
		part := parts[i]
		if next, ok := current[part]; ok {
			if nextMap, ok := next.(map[string]interface{}); ok {
				current = nextMap
			} else {
				return
			}
		} else {
			newMap := make(map[string]interface{})
			current[part] = newMap
			current = newMap
		}
	}

	finalKey := parts[len(parts)-1]
	// Security: prevent modification of restricted keys
	if finalKey == "__proto__" || finalKey == "constructor" {
		return
	}
	current[finalKey] = value
}

type WSMessage struct {
	Action string      `json:"action"`
	Path   string      `json:"path"`
	Value  interface{} `json:"value"`
}

func (s *Server) handleWS(w http.ResponseWriter, r *http.Request) {
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		http.Error(w, "missing tenant", http.StatusBadRequest)
		return
	}

	conn, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	config := s.getTenantConfig(tenantID)

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg WSMessage
		if err := json.Unmarshal(message, &msg); err != nil {
			continue
		}

		switch msg.Action {
		case "update":
			if msg.Path == "" {
				continue
			}
			s.applyUpdate(config, msg.Path, msg.Value)
			resp, _ := json.Marshal(map[string]string{"status": "ok"})
			conn.WriteMessage(websocket.TextMessage, resp)

		case "get":
			config.mu.RLock()
			resp, _ := json.Marshal(config.Properties)
			config.mu.RUnlock()
			conn.WriteMessage(websocket.TextMessage, resp)
		}
	}
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	srv := NewServer()
	http.HandleFunc("/ws", srv.handleWS)
	http.HandleFunc("/health", srv.handleHealth)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
